pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        uint256 countBefore = c.depositsCount();
        // We just call sendMoney; it may revert (e.g. if target is a contract that reverts)
        // We ignore revert: we only check that AFTER the call, depositsCount increased.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));
        // Ensure the call was executed (even if it reverted, the fallback was NOT triggered, so count unchanged)
        // But the assertion should hold only when the call succeeds? 
        // Actually the invariant says: after a call to sendMoney completes, depositsCount must be > countBefore.
        // If sendMoney reverts, it still "completes" but the fallback is NOT called, so count stays same. 
        // The reference C would have countBefore+1 only if the fallback was executed, but sendMoney does not trigger fallback.
        // So the rule "depositsCount increases" is false for sendMoney. Let me re-read the prompt.
        // The prompt says: "after a call to sendMoney(...) completes, the value of state variable depositsCount differs: P.depositsCount() != M.depositsCount()."
        // That means the reference C has some behavior that makes depositsCount different from M. But sendMoney does not call fallback.
        // Actually, the fallback is triggered when ETH is sent to C without data. sendMoney sends ETH to _target, not to C.
        // So how could depositsCount change? It would only change if sendMoney were called on C itself? No.
        // Wait: maybe the bug is that in the original C, the fallback increments depositsCount when ETH is sent to C.
        // But sendMoney sends ETH to _target, not to C. So depositsCount remains unchanged in both versions.
        // The difference could only be observed if we send ETH to C directly (via fallback). But the prompt says drive through sendMoney.
        // Let me re-read: "Driven through the public/external entry `sendMoney(address,uint256)`, P and M differ ... after a call to `sendMoney(...)` completes, the value of state variable `depositsCount` differs."
        // That would only be possible if sendMoney somehow triggers the fallback of C. It doesn't. So maybe the test is about something else.
        // Perhaps the intended rule: depositsCount is unchanged after sendMoney (since no fallback triggered). But then M also has unchanged count, so no difference.
        // I must be missing something. Maybe the fuzz call includes sending ETH along with sendMoney? The fallback is triggered when ETH is sent to C with empty calldata.
        // But sendMoney does not send ETH to C; it sends to _target. So no difference.
        // The only way depositsCount changes is if we call sendMoney with value !=0 AND the target is C itself? Then C would receive ETH via call, which could trigger its fallback if the call is empty? 
        // Actually, if _target is address(c) and _value > 0, then c.sendMoney(address(c), value) sends ETH to c via .call{value: value}(""), which has empty calldata, thus triggers fallback.
        // Yes! That's it. So the rule is: when calling sendMoney with target == address(this), depositsCount increases by 1.
        // For the reference, depositsCount increments; for the mutant, it doesn't.
        // So the general rule: if target == address(c), then depositsCount increases by 1; otherwise it stays same.
        // But the assertion must be a single formula. We can write: after sendMoney, depositsCount == countBefore + (target == address(c) ? 1 : 0).
        // Let's implement that.
        if (!ok) {
            // If sendMoney reverted, we cannot check the state change? Actually if it reverts, state is reverted too, so count stays same.
            // But the reference and mutant would both have countBefore (since revert undoes changes). So no difference.
            // So we only test when the call succeeds. But the prompt says "the reference C satisfies for all inputs and the buggy behavior breaks" - so we need to restrict to inputs where the call succeeds.
            // We can assume that for some targets, the call succeeds (e.g., a payable address). We'll bound target to be a payable address that accepts ETH.
        }
        // Actually, we can just check that when the call succeeds (ok == true), the invariant holds. But we need a general rule.
        // Perhaps simpler: we can check that depositsCount is either countBefore or countBefore+1, and the only way to get countBefore+1 is if target==address(c). 
        // But we need to make the test fail on mutant. For the mutant, depositsCount never increments, so condition target==address(c) would yield false positive difference.
        // So the rule: after sendMoney, depositsCount == countBefore + (target == address(c) ? 1 : 0). For the reference, this holds; for mutant, it fails when target==address(c).
        // We need to ensure the call succeeds. We can assume target is an address that accepts ETH, or we can use vm.assume to skip reverting calls.
        vm.assume(ok); // ensure the call succeeded
        uint256 expected = countBefore + (target == address(c) ? 1 : 0);
        assertTrue(c.depositsCount() == expected, "depositsCount mismatch");
    }
}

