contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // target cannot be zero address to avoid accidental burn
        vm.assume(target != address(0));
        // bound value to avoid overflow or excessive gas
        value = bound(value, 1, 100 ether);

        // Pre-call: fund the contract with some ether via the fallback
        vm.deal(address(c), value);

        // Record owner's balance before sendMoney
        address owner = c.owner();
        uint256 balanceBefore = owner.balance;

        // Call sendMoney to send value to the contract itself (so contract balance changes)
        c.sendMoney(target, value);

        // Now call withdrawAll
        c.withdrawAll();

        // Assert: the owner's balance increased by a non-zero amount (the full contract balance before withdraw)
        assertTrue(owner.balance > balanceBefore);
    }
}

