pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Bound value to avoid overflow and ensure non-trivial balance
        vm.assume(value > 0 && value <= type(uint128).max);
        // Ensure target is not the zero address to avoid wasting gas
        vm.assume(target != address(0));

        // Get the contract's initial balance (should be 0)
        uint256 initialBalance = address(c).balance;

        // Call sendMoney to deposit ether into the contract
        // We need to fund the caller (owner) with enough ether
        address owner = c.owner();
        vm.deal(owner, value);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        require(success, "sendMoney failed");

        // Now the contract should have at least value ether
        uint256 balanceBeforeWithdraw = address(c).balance;
        vm.assume(balanceBeforeWithdraw > 0);

        // Capture owner's balance before withdrawAll
        uint256 ownerBalanceBefore = address(owner).balance;

        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // The owner should have received the contract's entire balance
        uint256 ownerBalanceAfter = address(owner).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // General rule: After sendMoney and then withdrawAll, the contract balance becomes zero
        // and the owner's balance increases by the amount that was in the contract
        assertTrue(contractBalanceAfter == 0, "Contract balance not zero after withdrawAll");
    }
}

